    pts=[]
    for it in dr['items']:
        if it[0]=='l':
            pts.append((it[1].x,it[1].y)); pts.append((it[2].x,it[2].y))
        elif it[0]=='c':
            for q in it[1:5]: pts.append((q.x,q.y))
